// src/components/Navbar.jsx
import React from "react";
import { Link, useNavigate } from "react-router-dom";

const Navbar = () => {
  const navigate = useNavigate();

  const token = localStorage.getItem("access");
  const user = JSON.parse(localStorage.getItem("user"));
  const isAuth = Boolean(token && user);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/login");
    window.location.reload();
  };

  return (
    <nav
      style={{
        height: "80px",
        padding: "0 32px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        background: "#020617",
        borderBottom: "1px solid rgba(148,163,184,0.15)",
      }}
    >
      <Link
        to="/"
        style={{
          color: "#fbbf24",
          fontWeight: 700,
          fontSize: "18px",
          textDecoration: "none",
        }}
      >
        THESIS CHECK
      </Link>

      <div style={{ display: "flex", gap: "18px", alignItems: "center" }}>
        <Link to="/" style={{ color: "#e5e7eb" }}>Home</Link>
        <Link to="/about" style={{ color: "#e5e7eb" }}>About</Link>
        <Link to="/contact" style={{ color: "#e5e7eb" }}>Contact</Link>

        {isAuth && (
          <Link
            to="/dashboard"
            style={{
              color: "#111827",
              background: "#fbbf24",
              padding: "6px 14px",
              borderRadius: "999px",
              fontWeight: 600,
            }}
          >
            Dashboard
          </Link>
        )}

        {isAuth ? (
          <>
            <div style={{ textAlign: "right", fontSize: "12px" }}>
              <div style={{ opacity: 0.85 }}>{user.email}</div>
              <div
                style={{
                  color: "#22c55e",
                  fontWeight: 600,
                  fontSize: "11px",
                }}
              >
                {user.role}
              </div>
            </div>

            <button
              onClick={handleLogout}
              style={{
                border: "1px solid #ef4444",
                color: "#ef4444",
                background: "transparent",
                padding: "6px 14px",
                borderRadius: "999px",
                cursor: "pointer",
              }}
            >
              Logout
            </button>
          </>
        ) : (
          <Link
            to="/login"
            style={{
              color: "#fbbf24",
              border: "1px solid #fbbf24",
              padding: "6px 14px",
              borderRadius: "999px",
            }}
          >
            Log in
          </Link>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
